begin;
select '1..3' as tap;
create function pg_temp.require(ok boolean)returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'Overview assertion failed';end if;end$$;
grant execute on function pg_temp.require(boolean)to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333332',true);
select set_config('p13.id',public.create_task('22222222-2222-4222-8222-222222222221','{"title":"Fictional P13 next action","summary":"","body":"","leadUnitId":null,"parentId":null,"classification":"restricted","taskType":"ordinary","assigneeId":"33333333-3333-4333-8333-333333333332","assignedUnitId":null,"collaborators":[],"checklist":[],"dueOn":"2027-04-10","dueAt":null,"reason":"Synthetic overview"}',gen_random_uuid())->>'workItemId',true);
select pg_temp.require(jsonb_array_length(public.read_overview('22222222-2222-4222-8222-222222222221')->'items')=1);
select pg_temp.require(public.read_overview('22222222-2222-4222-8222-222222222221')->'items'->0->>'lane'='actionable');
select 'ok 1 - P13_A1: normalized rows are unique and form the only source of widget counts' as tap;
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333333',true);
select pg_temp.require(public.read_overview('22222222-2222-4222-8222-222222222221')->'items'='[]');
select pg_temp.require(public.read_overview('22222222-2222-4222-8222-222222222221')->>'hasMore'='false');
select 'ok 2 - P13_A2: unrelated restricted task/deliverable titles and aggregate overflow are absent' as tap;
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333332',true);
select public.transition_task(current_setting('p13.id')::uuid,'{"state":"done","reason":"Synthetic completion","evidence":"Fictional evidence"}',1,gen_random_uuid());
select pg_temp.require(public.read_overview('22222222-2222-4222-8222-222222222221')->'items'='[]');
select 'ok 3 - P13_A3: actual completion disappears on a fresh authoritative query' as tap;
rollback;
